#!/usr/bin/env bash
# Demo folder used in the video. Run in an empty directory (ideally in a container):
#   podman run --rm -it docker.io/library/debian:13 bash
set -euo pipefail
# needs: apt-get install -y curl python3
mkdir -p /lab/api && cd /lab/api
echo  | base64 -d > /opt/api.py
(setsid python3 /opt/api.py >/dev/null 2>&1 &); sleep 1
